target.css:
:root {
  --ink: #17233f;
  --paper: #ffffff;
  --mist: #f1f4fa;
  --line: #d9e0ed;
  --blue: #3567ee;
  --mint: #b9f1d3;
  --orange: #ffbe70;
  --lilac: #e5dcff;
  --muted: #64718a;
}

article {
  box-sizing: border-box;
  width: 500px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  overflow: hidden;
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 14px 11px;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
}

.mark {
  display: grid;
  width: 31px;
  height: 31px;
  place-items: center;
  color: var(--paper);
  background: var(--blue);
  border-radius: 9px;
  font-size: 19px;
  font-weight: 800;
}

.kicker,
.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.11em;
}

h1 {
  margin: 2px 0 0;
  font-size: 18px;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.shift {
  padding: 5px 8px;
  color: var(--blue);
  background: var(--mist);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.content {
  display: grid;
  grid-template-columns: 1.06fr 0.94fr;
  gap: 12px;
  padding: 12px 14px;
}

.route {
  padding: 12px;
  background: var(--mist);
  border-radius: 12px;
}

.route-code {
  margin: 4px 0 10px;
  color: var(--blue);
  font-size: 26px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: 0.03em;
}

.details {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.details p {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin: 0;
  padding: 6px 7px;
  background: var(--paper);
  border-radius: 7px;
}

.details span {
  color: var(--muted);
  font-size: 10px;
  line-height: 1;
}

.details strong {
  font-size: 13px;
  line-height: 1.1;
}

.lockers {
  padding: 11px 12px;
  color: var(--paper);
  background: var(--ink);
  border-radius: 12px;
}

h2 {
  margin: 0 0 7px;
  font-size: 12px;
  line-height: 1;
  letter-spacing: 0.02em;
}

ul {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 7px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
}

.ready { background: var(--mint); color: var(--ink); }
.loading { background: var(--orange); color: var(--ink); }
.held { background: var(--lilac); color: var(--ink); }

.slot-state {
  font-size: 10px;
  font-weight: 800;
}

footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px 13px;
  border-top: 1px solid var(--line);
}

footer p {
  display: flex;
  gap: 5px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 600;
}

time {
  color: var(--ink);
  font-weight: 800;
}

button {
  padding: 8px 10px;
  color: var(--paper);
  background: var(--blue);
  border: 0;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 800;
}

